def calculate_position_value_C2() -> None:
    """Calculates position value."""
    global investment_master_C2
    investment_master_C2.inv_market_value = investment_master_C2.inv_quantity * investment_master_C2.inv_current_price

def calculate_gain_loss_C2() -> None:
    """Calculates gain or loss."""
    global investment_master_C2
    investment_master_C2.inv_gain_loss = investment_master_C2.inv_market_value - (investment_master_C2.inv_quantity * investment_master_C2.inv_purchase_price)

