def main_loop_C5() -> None:
    """Main loop processing."""
    global WS_NOT_EOF, WS_EOF, WS_CUST_COUNT
    WS_NOT_EOF = True
    WS_EOF = False
    WS_CUST_COUNT = 0
    while not WS_EOF:
        try:
            customer_data = read_customer_master_C5()
            update_profile_C5()
            enrich_profile_C5()
            WS_CUST_COUNT += 1
        except EOFError:
            WS_EOF = True

def read_customer_master_C5() -> str:
    """Reads customer master data."""
    global CUSTOMER_MASTER
    try:
        return CUSTOMER_MASTER
    except:
        raise EOFError

