def load_batch_header_C5() -> None:
    """Loads batch header information."""
    global BATCH_FILE, WS_BATCH_HEADER, WS_CURRENT_BATCH, BATCH_COUNT, BATCH_TOTAL, WS_BATCH_EOF
    global WS_EXPECTED_COUNT, WS_EXPECTED_TOTAL
    try:
        batch_file_lines = open("BATCH_FILE", "r").readlines()
        if not batch_file_lines:
            WS_BATCH_EOF = 'Y'
            return
        WS_BATCH_HEADER = batch_file_lines[0].strip()
        WS_CURRENT_BATCH = WS_BATCH_HEADER[:10].strip()
        BATCH_COUNT = int(WS_BATCH_HEADER[10:15].strip())
        BATCH_TOTAL = Decimal(WS_BATCH_HEADER[15:].strip())
        WS_EXPECTED_COUNT  = None  # TODO: was BATCH_COUNT
        WS_EXPECTED_TOTAL  = None  # TODO: was BATCH_TOTAL
        WS_BATCH_EOF = 'N'
    except FileNotFoundError:
        WS_BATCH_EOF = 'Y'

def process_batch_items_C5() -> None:
    """Processes batch items from file."""
    global BATCH_FILE, WS_BATCH_ITEM, WS_BATCH_EOF, WS_ACTUAL_COUNT, WS_ACTUAL_TOTAL
    global ITEM_AMOUNT
    try:
        batch_file = open("BATCH_FILE", "r")
        lines = batch_file.readlines()
        batch_file.close()
        for i in range(1, len(lines)): # Start from the second line (after header)
            WS_BATCH_ITEM = lines[i].strip()
            if not WS_BATCH_ITEM: #Skip empty lines
                continue
            WS_ACTUAL_COUNT += 1
            try:
                ITEM_AMOUNT = Decimal(WS_BATCH_ITEM[10:])
            except:
                ITEM_AMOUNT = Decimal("0")
            WS_ACTUAL_TOTAL += None  # TODO: was ITEM_AMOUNT
            process_single_item_C5()

    except FileNotFoundError:
        WS_BATCH_EOF = 'Y'

    except Exception as e:
        print (e)
        WS_BATCH_EOF = 'Y'

def process_single_item_C5() -> None:
    """Processes a single item within the batch."""
    global ITEM_TYPE
    ITEM_TYPE = WS_BATCH_ITEM[:3].strip()
    if ITEM_TYPE == 'PAY':
        process_payment_C5()
    elif ITEM_TYPE == 'REF':
        process_refund_C5()
    elif ITEM_TYPE == 'ADJ':
        process_adjustment_C5()

def process_payment_C5() -> None:
    """Processes payment items within the batch."""
