def process_shipment_C11() -> None:
    """Process shipment."""
    global SHIP_METHOD, SHIP_EST_DELIVERY
    global WS_PROCESS_DATE, SHIPMENT_RECORD, WS_SHIPMENT_RECORD
    if True:
        SHIP_METHOD = 'EXPRESS'
        SHIP_EST_DELIVERY = int(WS_PROCESS_DATE) + 2
    else:
        SHIP_METHOD = 'STANDARD'
        SHIP_EST_DELIVERY = int(WS_PROCESS_DATE) + 7
    pass

def card_blocking_C11() -> None:
    """Card blocking."""
    global CARD_STATUS, WS_BLOCK_REASON, CARD_BLOCK_REASON
