    global WS_RETURN_TRAILER, RETURN_RECORD_TYPE, WS_RETURN_COUNT
    global RETURN_ENTRY_COUNT, WS_RETURN_TOTAL, RETURN_TOTAL_AMOUNT
    RETURN_RECORD_TYPE = '9'
