def validate_auth_code_C12() -> None:
    """Validates authorization code."""
    global WS_AUTH_VALID, WS_CAPTURE_AUTH_CODE, AUTH_SEARCH_KEY, AUTH_FILE, WS_AUTH_REC, AUTH_REC_STATUS
    WS_AUTH_VALID = 'N'
    AUTH_SEARCH_KEY = WS_CAPTURE_AUTH_CODE
    auth_rec = read_auth_file_C12(AUTH_SEARCH_KEY)

    if auth_rec:
        WS_AUTH_REC = auth_rec
        if WS_AUTH_REC["AUTH_REC_STATUS"] == 'P':
            WS_AUTH_VALID = 'Y'
    else:
        WS_AUTH_VALID = 'N'

def create_capture_record_C12() -> None:
    """Creates a capture record."""
    global AUTH_REC_STATUS, AUTH_RECORD, WS_AUTH_REC, WS_CAPTURE_RECORD, AUTH_REC_CARD, CAPTURE_CARD, WS_CAPTURE_AMOUNT, CAPTURE_AMOUNT, WS_CAPTURE_AUTH_CODE, CAPTURE_AUTH_CODE, WS_PROCESS_DATE, CAPTURE_DATE, CAPTURE_RECORD
    AUTH_REC_STATUS = 'C'
    WS_AUTH_REC["AUTH_REC_STATUS"]  = None  # TODO: was AUTH_REC_STATUS
