def close_revenue_expense_C14() -> None:
    """Closes revenue and expense accounts."""
    global ws_net_income, ws_eof_flag
    ws_net_income = 0
    ws_eof_flag = 'N'
    while ws_eof_flag == 'N':
        try:
            ws_gl_record = read_gl_master_file()
            if gl_revenue:
                ws_net_income += ws_gl_net_balance
                ws_gl_debit_balance = 0
                ws_gl_credit_balance = 0
                ws_gl_net_balance = 0
                rewrite_gl_record(ws_gl_record)
            if gl_expense:
                ws_net_income -= ws_gl_net_balance
                ws_gl_debit_balance = 0
                ws_gl_credit_balance = 0
                ws_gl_net_balance = 0
                rewrite_gl_record(ws_gl_record)
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

