def match_intercompany_pairs_C15():
    """Match intercompany balance pairs."""
    ws_ic_idx = 1
    while ws_ic_idx <= ws_ic_count:
        find_intercompany_counterpart_C15(ws_ic_idx)
        ws_ic_idx += 1

def find_intercompany_counterpart_C15(ws_ic_idx: int):
    """Find matching counterpart for intercompany balances."""
    ws_search_from = ic_from_entity[ws_ic_idx]
    ws_search_to = ic_to_entity[ws_ic_idx]
    ws_ic_idx2 = 1
    while ws_ic_idx2 <= ws_ic_count:
        if ic_from_entity[ws_ic_idx2] == ws_search_to:
            if ic_to_entity[ws_ic_idx2] == ws_search_from:
                ws_ic_diff = ic_amount[ws_ic_idx] + ic_amount[ws_ic_idx2]
                if ws_ic_diff != Decimal('0'):
                    log_intercompany_difference_C15()
                break
        ws_ic_idx2 += 1

def log_intercompany_difference_C15():
    """Log intercompany difference."""
    initialize_ws_ic_diff_rec_C15()
    icd_from = ws_search_from
    icd_to = ws_search_to
