def rotate_encryption_key_C15():
    """Rotate encryption key periodically."""
    if ws_key_age_days > 90:
        genkey(ws_new_key)
        ws_old_key = ws_encryption_key
        ws_encryption_key = ws_new_key
        reencrypt_data_C15()

def reencrypt_data_C15():
    """Re-encrypt existing data with the new encryption key."""
    ws_eof_flag = 'N'
    while ws_eof_flag == 'N':
        try:
            ws_enc_record = read_encrypted_data_file_C15()
            aes256dec(enc_data, ws_old_key, ws_decrypted_data)
            aes256enc(ws_decrypted_data, ws_encryption_key, ws_reencrypted_data)
            enc_data = ws_reencrypted_data
            rewrite_encrypted_data_record_C15()
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

